            s!(a[i], a[u!(j)]);
        }
        a.to_vec()
    }};
}
```

And in the main loop:
```rust
loop {
    let n = i!();
    let m = [n.as_bytes(), f.as_bytes()].concat();
    let mut c = vec![];
    for b in m.iter() {
        let mut k: T = 0;
