from pwn import *
import sys
import binascii

def get_encryption(input_data=""):
    # Connect to remote service
    conn = remote("crypto.chal.csaw.io", 4512)

    # Send input data if any
    if input_data:
        conn.sendline(input_data.encode())
    else:
        conn.sendline(b"")

    # Get response
    response = conn.recvall().decode().strip()
    conn.close()

    # Extract hex from response and convert to bytes
    hex_output = response.split("\n")[-1]  # Get last line containing hex
    return bytes.fromhex(hex_output)

def analyze_differences():
    # Get baseline encryption (empty input)
    print("[*] Getting baseline encryption...")
    baseline = get_encryption()
    print(f"[+] Baseline (empty input): {baseline.hex()}")

    # Test with single characters
    test_chars = ['A', 'B', 'C', 'D', 'E']
    results = {}

    print("\n[*] Testing single character inputs...")
    for char in test_chars:
        encrypted = get_encryption(char)
        diff = bytes(a ^ b for a, b in zip(baseline, encrypted))
        results[char] = {
            'encrypted': encrypted,
            'diff': diff
        }
        print(f"\n[+] Input '{char}':")
        print(f"    Encrypted: {encrypted.hex()}")
        print(f"    XOR diff with baseline: {diff.hex()}")

        # Analyze pattern in first block
        print(f"    First block differences:")
        for i, (b1, b2) in enumerate(zip(baseline[:16], encrypted[:16])):
            if b1 != b2:
                print(f"      Position {i}: {b1:02x} -> {b2:02x} (diff: {b1^b2:02x})")

def main():
    try:
        analyze_differences()
    except Exception as e:
        print(f"[-] Error: {str(e)}")

if __name__ == "__main__":
    main()

